from copy import deepcopy
from typing import Any


def _validate(releases: list[dict[str, Any]]) -> None:
    if not isinstance(releases, list):
        raise ValueError("releases must be a list")
    seen: set[str] = set()
    for release in releases:
        if not isinstance(release, dict):
            raise ValueError("each release must be a dictionary")
        required = {"slug", "headline", "body", "published_at", "state"}
        if not required.issubset(release):
            raise ValueError("release is missing required fields")
        if not isinstance(release["slug"], str) or not release["slug"]:
            raise ValueError("slug must be a non-empty string")
        if release["slug"] in seen:
            raise ValueError("slugs must be unique")
        seen.add(release["slug"])
        if not isinstance(release["headline"], str) or not release["headline"]:
            raise ValueError("headline must be a non-empty string")
        if not isinstance(release["body"], str):
            raise ValueError("body must be a string")
        if not isinstance(release["published_at"], int) or isinstance(release["published_at"], bool):
            raise ValueError("published_at must be an integer")
        if release["state"] not in {"public", "draft"}:
            raise ValueError("invalid state")


class ReleaseIndex:
    """Validate releases and produce a newest-first snapshot of public entries."""

    def render(self, releases: list[dict[str, Any]]) -> list[dict[str, Any]]:
        _validate(releases)
        public = (release for release in releases if release["state"] == "public")
        ordered = sorted(public, key=lambda release: (-release["published_at"], release["slug"]))
        return deepcopy(ordered)


class ReleaseDetail:
    """Validate releases and return one isolated public entry selected by slug."""

    def render(self, releases: list[dict[str, Any]], slug: str) -> dict[str, Any]:
        _validate(releases)
        if not isinstance(slug, str) or not slug:
            raise ValueError("slug must be a non-empty string")
        for release in releases:
            if release["slug"] == slug:
                return deepcopy(release)
        raise KeyError(slug)

